 * side effect, and uses only the supplied evaluation time. Relative TTLs require
 * an explicit asOfMs (or createdAtMs), while absolute expiries can be checked by
 * passing a fixed asOfMs as well.
 */
export function recoverCheckpointAttachmentBindings(
  bindings: readonly CheckpointAttachmentInput[],
  options: CheckpointAttachmentRecoveryOptions | number = {},
): CheckpointAttachmentRecoveryResult {
  const asOfMs = typeof options === "number" ? options : (options.asOfMs ?? 0);
  const recovered: CheckpointAttachmentBinding[] = [];
  const rejected: CheckpointAttachmentRepair[] = [];
  const firstValidHashByRef = new Map<string, { hash: string; binding: CheckpointAttachmentBinding }>();

  for (const raw of bindings) {
    const input: CheckpointAttachmentInput = isRecord(raw) ? raw : {};
