): CheckpointAttachmentRepair {
  const ref = nonEmptyString(input.attachmentRef);
  const kind = typeof (input.kind ?? input.type) === "string" ? ((input.kind ?? input.type) as string) : null;
  const hash = typeof input.contentHash === "string" ? input.contentHash.toLowerCase() : null;
  const owner = nonEmptyString(input.owner);
  return {
    attachmentRef: ref,
    kind,
    contentHash: hash,
    owner,
    status,
    reason,
    ...details,
  };
}

function compareBindings(a: CheckpointAttachmentBinding, b: CheckpointAttachmentBinding): number {
  return (
    a.attachmentRef.localeCompare(b.attachmentRef) ||
    a.kind.localeCompare(b.kind) ||
    a.contentHash.localeCompare(b.contentHash) ||
    a.owner.localeCompare(b.owner) ||
    a.expiresAtMs - b.expiresAtMs
  );
}

function compareRepairs(a: CheckpointAttachmentRepair, b: CheckpointAttachmentRepair): number {
  return (
    (a.attachmentRef ?? "").localeCompare(b.attachmentRef ?? "") ||
    (a.kind ?? "").localeCompare(b.kind ?? "") ||
    (a.status ?? "").localeCompare(b.status ?? "") ||
    (a.contentHash ?? "").localeCompare(b.contentHash ?? "") ||
    (a.owner ?? "").localeCompare(b.owner ?? "") ||
    a.reason.localeCompare(b.reason)
  );
}

/**
 * Recover a checkpoint's restricted attachment references.
 *
 * The function is pure: it does not mutate the input, reads no clock, executes no
 * side effect, and uses only the supplied evaluation time. Relative TTLs require
 * an explicit asOfMs (or createdAtMs), while absolute expiries can be checked by
 * passing a fixed asOfMs as well.
 */
export function recoverCheckpointAttachmentBindings(
  bindings: readonly CheckpointAttachmentInput[],
  options: CheckpointAttachmentRecoveryOptions | number = {},
): CheckpointAttachmentRecoveryResult {
  const asOfMs = typeof options === "number" ? options : (options.asOfMs ?? 0);
  const recovered: CheckpointAttachmentBinding[] = [];
  const rejected: CheckpointAttachmentRepair[] = [];
  const firstValidHashByRef = new Map<string, { hash: string; binding: CheckpointAttachmentBinding }>();

  for (const raw of bindings) {
    const input: CheckpointAttachmentInput = isRecord(raw) ? raw : {};
    const ref = nonEmptyString(input.attachmentRef);
    const kind = resolveKind(input);
    const hash = resolveHash(input);
    const owner = nonEmptyString(input.owner);
    const expiry = resolveExpiry(input, asOfMs);

    if (kind === null) {
      rejected.push(repair(input, "invalid-kind", `kind must be one of: ${CHECKPOINT_ATTACHMENT_KINDS.join(", ")}`));
      continue;
    }
    if (ref === null) {
      rejected.push(repair(input, "invalid-ref", "attachmentRef must be a non-empty string"));
      continue;
    }
    if (hash.error === "missing") {
      rejected.push(repair(input, "missing-hash", "contentHash is required"));
      continue;
    }
    if (hash.error === "invalid" || hash.value === null) {
      rejected.push(repair(input, "invalid-hash", "contentHash must be a 64-character SHA-256 hexadecimal digest"));
      continue;
    }
    if (owner === null) {
      rejected.push(repair(input, "missing-owner", "owner is required"));
      continue;
    }
    if (expiry.error === "missing") {
      rejected.push(repair(input, "missing-ttl", "a TTL or absolute expiry is required"));
      continue;
    }
    if (expiry.error === "invalid" || expiry.expiresAtMs === null) {
      rejected.push(repair(input, "invalid-ttl", "TTL must contain a non-negative duration and creation time, or an absolute expiry"));
      continue;
    }
    if (expiry.expiresAtMs <= asOfMs) {
      rejected.push(repair(input, "expired", "attachment TTL has expired"));
      continue;
    }
    if (input.cursor !== undefined || input.blob !== undefined || input.data !== undefined || input.payload !== undefined || input.content !== undefined) {
      rejected.push(repair(input, "invalid-payload", "checkpoint attachments may contain references only, not cursors, blobs, or payloads"));
      continue;
    }

    const binding: CheckpointAttachmentBinding = {
      attachmentRef: ref,
      kind,
      contentHash: hash.value,
      owner,
      expiresAtMs: expiry.expiresAtMs,
    };
    const first = firstValidHashByRef.get(ref);
    if (first !== undefined && first.hash !== binding.contentHash) {
      rejected.push(
        repair(input, "conflict", "attachmentRef is already bound to a different content hash; the first binding is preserved", {
          conflictingWithHash: first.hash,
        }),
      );
      continue;
    }
    if (first !== undefined) {
      rejected.push(repair(input, "duplicate", "duplicate attachmentRef and contentHash binding was removed"));
      continue;
    }

    firstValidHashByRef.set(ref, { hash: binding.contentHash, binding });
    recovered.push(binding);
  }

  recovered.sort(compareBindings);
  rejected.sort(compareRepairs);

  const digestInput = {
    recovered: recovered as unknown as JsonValue,
    rejected: rejected as unknown as JsonValue,
  };
  const digest = sha256(canonicalJson(digestInput));

  return {
    recovered,
    rejected,
    states: rejected,
    digest,
  };
}

export const recoverCheckpointAttachments = recoverCheckpointAttachmentBindings;
export const recoverAttachmentBindings = recoverCheckpointAttachmentBindings;\n
export function checkpointAttachmentRecoveryDigest(result: CheckpointAttachmentRecoveryResult): string {
  return sha256(
    canonicalJson({
      recovered: result.recovered as unknown as JsonValue,
      rejected: result.rejected as unknown as JsonValue,
    }),
  );
}
"},{"path":"harness/specs/tasks/harness-gap-checkpoint-attachment-binding.md","content":"# L04 — Checkpoint attachment binding contract

## Scope

A persisted checkpoint may contain only these restricted reference kinds:

1. `task-attachment`
2. `recovery-instruction`
3. `context`
4. `external-artifact-ref`
5. `ledger-checkpoint`

Arbitrary cursors, blobs, payloads, and inline content are not valid checkpoint attachments. The runtime representation contains reference metadata only.

## Required binding metadata

Every binding must provide:

- `attachmentRef`: a non-empty reference identifier;
- `kind`: one of the five kinds above;
- `contentHash`: exactly 64 hexadecimal characters representing a SHA-256 digest;
- `owner`: a non-empty owner identifier;
- a TTL, expressed either as an absolute expiry (`expiresAtMs` or `expiresAt`) or as a duration (`ttlMs`/`ttlSeconds`/`ttl`) plus `createdAtMs`.

The implementation also accepts the kind under the compatibility field `type`. Compatibility fields do not broaden the set of permitted kinds.

## Recovery rules

`recoverCheckpointAttachmentBindings(bindings, options)` is a pure function. It does not mutate its input, read a clock, execute effects, or invoke recovery actions. `options.asOfMs` is a caller-supplied fixed evaluation time. A numeric second argument is accepted as shorthand for `{ asOfMs }`.

Recovery produces two explicit collections:

- `recovered`: valid, unique, unexpired bindings;
- `rejected`: explicit repair states. `states` is an alias of `rejected` for callers that use state terminology.

The following conditions are never silently accepted:

| Condition | Explicit state | Included in `recovered` |
| --- | --- | --- |
| Missing `contentHash` | `missing-hash` | No |
| Malformed `contentHash` | `invalid-hash` | No |
| Missing `owner` | `missing-owner` | No |
| Missing TTL | `missing-ttl` | No |
| Invalid TTL | `invalid-ttl` | No |
| Expiry at or before `asOfMs` | `expired` | No |
| Same `attachmentRef`, different valid hash | `conflict` | No; the first binding is preserved |
| Same `attachmentRef` and hash | `duplicate` | No; the first binding is preserved |
| Unsupported kind | `invalid-kind` | No |
| Empty reference | `invalid-ref` | No |
| Inline payload/blob/cursor | `invalid-payload` | No |

A conflict state includes `conflictingWithHash`, which identifies the hash retained from the first binding. Hashes are normalized to lowercase before comparison.

## Determinism and digest

Recovered bindings and repair states are sorted deterministically. The `digest` field is the lowercase SHA-256 hex digest of a canonical JSON representation containing both `recovered` and `rejected`. Consequently, missing and conflicting inputs affect the digest and remain auditable.

Calling recovery repeatedly with the same input and the same `asOfMs` returns the same content and digest. Recovery itself never reruns the side effects associated with a task attachment, recovery instruction, context reference, external artifact, or ledger checkpoint.

## Minimal example

```ts
import { recoverCheckpointAttachmentBindings } from "../../../openclaw_runtime/src/runtime-core/checkpoint-attachment-binding";

const hash = "a".repeat(64);
const result = recoverCheckpointAttachmentBindings(
  [
    {
      attachmentRef: "artifact:invoice-1",
      kind: "external-artifact-ref",
      contentHash: hash,
      owner: "billing-worker",
      expiresAtMs: 2_000,
    },
    {
      attachmentRef: "artifact:invoice-1",
      kind: "external-artifact-ref",
      contentHash: "b".repeat(64),
      contentHash: "b".repeat(64),
      owner: "billing-worker",
      expiresAtMs: 2_000,
    },
  ],
  { asOfMs: 1_000 },
);

// result.recovered.length === 1
// result.rejected[0].status === "conflict"
// result.recovered[0].contentHash === hash
```

The duplicated `contentHash` line above is intentionally harmless in JavaScript (the later value wins), but production examples should contain each property only once.

## Acceptance checks

- Enumerate all five kinds and reject any sixth kind.
- Exercise missing and malformed hashes, missing owner, expired TTL, duplicate reference/hash, and conflicting reference/hash.
- Verify rejected entries are excluded from `recovered` and carry explicit statuses.
- Deep-freeze the input before recovery and verify it is unchanged.
- Invoke recovery twice with a fixed `asOfMs` and compare both the result and digest.
- Verify the digest is 64 lowercase hexadecimal characters and can be recomputed with `checkpointAttachmentRecoveryDigest`.
- Scan the implementation and documentation for credentials; expected credential-scan matches are zero.
